using System.Collections.Generic;

public class Solution {
    public IList<string> AmbiguousCoordinates(string s) {
        var result = new List<string>();
        string digits = s.Substring(1, s.Length - 2);

        for (int split = 1; split < digits.Length; split++) {
            var left = GenerateNumbers(digits.Substring(0, split));
            var right = GenerateNumbers(digits.Substring(split));

            foreach (string x in left) {
                foreach (string y in right) {
                    result.Add("(" + x + ", " + y + ")");
                }
            }
        }

        return result;
    }

    private List<string> GenerateNumbers(string digits) {
        var numbers = new List<string>();

        if (digits.Length == 1 || digits[0] != '0') {
            numbers.Add(digits);
        }

        if (digits[digits.Length - 1] == '0') {
            return numbers;
        }

        for (int point = 1; point < digits.Length; point++) {
            if (digits[0] == '0' && point > 1) {
                break;
            }

            numbers.Add(digits.Substring(0, point) + "." + digits.Substring(point));
        }

        return numbers;
    }
}
