public class Solution {
    public int[] HitBricks(int[][] grid, int[][] hits) {
        int rows = grid.Length;
        int cols = grid[0].Length;
        int roof = rows * cols;

        int[][] remaining = new int[rows][];
        for (int r = 0; r < rows; r++) {
            remaining[r] = (int[])grid[r].Clone();
        }

        bool[] removed = new bool[hits.Length];
        for (int i = 0; i < hits.Length; i++) {
            int r = hits[i][0];
            int c = hits[i][1];
            if (remaining[r][c] == 1) {
                removed[i] = true;
                remaining[r][c] = 0;
            }
        }

        DisjointSet dsu = new DisjointSet(roof + 1);

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (remaining[r][c] == 0) continue;

                int id = r * cols + c;
                if (r == 0) dsu.Union(id, roof);
                if (r > 0 && remaining[r - 1][c] == 1) {
                    dsu.Union(id, id - cols);
                }
                if (c > 0 && remaining[r][c - 1] == 1) {
                    dsu.Union(id, id - 1);
                }
            }
        }

        int[] result = new int[hits.Length];
        int[] directions = { -1, 0, 1, 0, -1 };

        // Restore bricks in reverse and count newly roof-connected bricks.
        for (int i = hits.Length - 1; i >= 0; i--) {
            if (!removed[i]) continue;

            int r = hits[i][0];
            int c = hits[i][1];
            int id = r * cols + c;
            int before = dsu.ComponentSize(roof);

            remaining[r][c] = 1;
            if (r == 0) dsu.Union(id, roof);

            for (int d = 0; d < 4; d++) {
                int nr = r + directions[d];
                int nc = c + directions[d + 1];

                if (nr >= 0 && nr < rows &&
                    nc >= 0 && nc < cols &&
                    remaining[nr][nc] == 1) {
                    dsu.Union(id, nr * cols + nc);
                }
            }

            int gained = dsu.ComponentSize(roof) - before - 1;
            result[i] = gained > 0 ? gained : 0;
        }

        return result;
    }

    private sealed class DisjointSet {
        private readonly int[] parent;
        private readonly int[] size;

        public DisjointSet(int count) {
            parent = new int[count];
            size = new int[count];
            for (int i = 0; i < count; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        private int Find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        public void Union(int a, int b) {
            int rootA = Find(a);
            int rootB = Find(b);
            if (rootA == rootB) return;

            if (size[rootA] < size[rootB]) {
                int temp = rootA;
                rootA = rootB;
                rootB = temp;
            }

            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        public int ComponentSize(int x) {
            return size[Find(x)];
        }
    }
}
