public class Solution {
    public bool CheckStraightLine(int[][] coordinates) {
        long x0 = coordinates[0][0];
        long y0 = coordinates[0][1];
        long dx = coordinates[1][0] - x0;
        long dy = coordinates[1][1] - y0;

