public class Solution {
    public int Clumsy(int n) {
        int result = 0;
        int term = n;
        int sign = 1;
        int operation = 0;

        for (int value = n - 1; value >= 1; value--) {
            switch (operation) {
                case 0:
                    term *= value;
                    break;
                case 1:
                    term /= value;
                    break;
                case 2:
                case 3:
                    result += sign * term;
                    term = value;
                    sign = operation == 2 ? 1 : -1;
                    break;
            }

            operation = (operation + 1) % 4;
        }

        return result + sign * term;
    }
}
