public class Solution {
    public int[] NumSmallerByFrequency(string[] queries, string[] words) {
        int[] suffixCounts = new int[12];

        foreach (string word in words) {
            suffixCounts[SmallestFrequency(word)]++;
        }

        for (int frequency = 10; frequency >= 1; frequency--) {
            suffixCounts[frequency] += suffixCounts[frequency + 1];
        }

        int[] answer = new int[queries.Length];
        for (int i = 0; i < queries.Length; i++) {
            answer[i] = suffixCounts[SmallestFrequency(queries[i]) + 1];
        }

        return answer;
    }

    private static int SmallestFrequency(string s) {
        char smallest = s[0];
        int frequency = 0;

        foreach (char c in s) {
            if (c < smallest) {
                smallest = c;
                frequency = 1;
            } else if (c == smallest) {
                frequency++;
            }
        }

        return frequency;
    }
}
