public class Solution {
    public int CountMaxOrSubsets(int[] nums) {
        int target = 0;
        foreach (int num in nums) {
            target |= num;
        }

        return Count(0, 0);

        int Count(int index, int currentOr) {
            if (currentOr == target) {
                return 1 << (nums.Length - index);
            }

            if (index == nums.Length) {
                return 0;
            }

            return Count(index + 1, currentOr)
                 + Count(index + 1, currentOr | nums[index]);
        }
    }
}
