public class Solution {
    public bool CanCross(int[] stones) {
        int n = stones.Length;

        for (int i = 1; i < n; i++) {
            if (stones[i] - stones[i - 1] > i) {
                return false;
            }
        }

        bool[,] dp = new bool[n, n + 1];
        dp[0, 0] = true;

        for (int i = 1; i < n; i++) {
            for (int j = i - 1; j >= 0; j--) {
                int jump = stones[i] - stones[j];

                if (jump > j + 1) {
                    break;
                }

                dp[i, jump] = dp[j, jump - 1]
                           || dp[j, jump]
                           || dp[j, jump + 1];

                if (i == n - 1 && dp[i, jump]) {
                    return true;
                }
            }
        }

        return false;
    }
}
