public class Solution {
    public int LongestStrChain(string[] words) {
        Array.Sort(words, (a, b) => a.Length.CompareTo(b.Length));

        var dp = new Dictionary<string, int>(StringComparer.Ordinal);
        int longest = 0;

        foreach (string word in words) {
            int best = 1;

            for (int i = 0; i < word.Length; i++) {
                string predecessor = word.Remove(i, 1);

                if (dp.TryGetValue(predecessor, out int previous)) {
                    best = Math.Max(best, previous + 1);
                }
            }

            dp[word] = best;
            longest = Math.Max(longest, best);
        }

        return longest;
    }
}
