public class Solution {
    public int MaxPoints(int[][] points) {
        int n = points.Length;
        if (n <= 2) return n;

        int answer = 2;

        for (int i = 0; i < n; i++) {
            if (answer >= n - i) break;

            var counts = new Dictionary<(int dx, int dy), int>();

            for (int j = i + 1; j < n; j++) {
                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];

                int gcd = Gcd(Math.Abs(dx), Math.Abs(dy));
                dx /= gcd;
                dy /= gcd;

                if (dx < 0 || (dx == 0 && dy < 0)) {
                    dx = -dx;
                    dy = -dy;
                }

                var slope = (dx, dy);
                counts.TryGetValue(slope, out int count);
                counts[slope] = ++count;

                answer = Math.Max(answer, count + 1);
            }
        }

        return answer;
    }

    private static int Gcd(int a, int b) {
        while (b != 0) {
            int remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    }
}
