public class Solution {
    public int MaxScore(int[] nums) {
        int length = nums.Length;
        int[,] gcd = new int[length, length];

        for (int i = 0; i < length; i++) {
            for (int j = i + 1; j < length; j++) {
                int a = nums[i];
                int b = nums[j];

                while (b != 0) {
                    int remainder = a % b;
                    a = b;
                    b = remainder;
                }

                gcd[i, j] = a;
            }
        }

        int stateCount = 1 << length;
        int[] dp = new int[stateCount];
        int[] bitCount = new int[stateCount];

        for (int mask = 1; mask < stateCount; mask++) {
            bitCount[mask] = bitCount[mask >> 1] + (mask & 1);
            if ((bitCount[mask] & 1) != 0) {
                continue;
            }

            int operation = bitCount[mask] / 2;

            for (int i = 0; i < length; i++) {
                if ((mask & (1 << i)) == 0) {
                    continue;
                }

                for (int j = i + 1; j < length; j++) {
                    if ((mask & (1 << j)) == 0) {
                        continue;
                    }

                    int previousMask = mask ^ (1 << i) ^ (1 << j);
                    int score = dp[previousMask] + operation * gcd[i, j];

                    if (score > dp[mask]) {
                        dp[mask] = score;
                    }
                }
            }
        }

        return dp[stateCount - 1];
    }
}
