public class Solution {
    public int MaximumANDSum(int[] nums, int numSlots) {
        int[] powers = new int[numSlots + 1];
        powers[0] = 1;
        for (int i = 1; i <= numSlots; i++) {
            powers[i] = powers[i - 1] * 3;
        }

        int stateCount = powers[numSlots];
        int[] dp = new int[stateCount];
        int[] placed = new int[stateCount];

        for (int state = 1; state < stateCount; state++) {
            dp[state] = -1;
            placed[state] = placed[state / 3] + state % 3;
        }

        int answer = 0;

        for (int state = 0; state < stateCount; state++) {
            if (dp[state] < 0) {
                continue;
            }

            int index = placed[state];
            if (index == nums.Length) {
                answer = System.Math.Max(answer, dp[state]);
                continue;
            }

            int digits = state;
            for (int slot = 0; slot < numSlots; slot++) {
                int occupancy = digits % 3;
                digits /= 3;

                if (occupancy == 2) {
                    continue;
                }

                int nextState = state + powers[slot];
                int score = dp[state] + (nums[index] & (slot + 1));
                dp[nextState] = System.Math.Max(dp[nextState], score);
            }
        }

        return answer;
    }
}
