public class Solution {
    public int MaxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.Length;
        int n = students[0].Length;
        int[,] scores = new int[m, m];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) {
                        scores[i, j]++;
                    }
                }
            }
        }

        int stateCount = 1 << m;
        int[] dp = new int[stateCount];
        int[] bitCount = new int[stateCount];

        for (int mask = 1; mask < stateCount; mask++) {
            bitCount[mask] = bitCount[mask >> 1] + (mask & 1);
        }

        for (int mask = 0; mask < stateCount - 1; mask++) {
            int student = bitCount[mask];

            for (int mentor = 0; mentor < m; mentor++) {
                int bit = 1 << mentor;
                if ((mask & bit) != 0) {
                    continue;
                }

                int nextMask = mask | bit;
                int candidate = dp[mask] + scores[student, mentor];

                if (candidate > dp[nextMask]) {
                    dp[nextMask] = candidate;
                }
            }
        }

        return dp[stateCount - 1];
    }
}
