public class Solution {
    public long MaximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        System.Array.Sort(flowers);

        int n = flowers.Length;
        int incomplete = 0;
        while (incomplete < n && flowers[incomplete] < target) {
            incomplete++;
        }

        long[] prefix = new long[incomplete + 1];
        for (int i = 0; i < incomplete; i++) {
            prefix[i + 1] = prefix[i] + flowers[i];
        }

        long answer = 0;
        long budget = newFlowers;

        for (int remaining = incomplete; remaining >= 0; remaining--) {
            if (budget < 0) {
                break;
            }

            long beauty = (long)(n - remaining) * full;

            if (remaining > 0) {
                int low = 1;
                int high = remaining;

                while (low < high) {
                    int mid = low + (high - low + 1) / 2;
                    long cost = (long)flowers[mid - 1] * mid - prefix[mid];

                    if (cost <= budget) {
                        low = mid;
                    } else {
                        high = mid - 1;
                    }
                }

                long minimum = System.Math.Min(
                    (long)target - 1,
                    (budget + prefix[low]) / low
                );

                beauty += minimum * partial;
            }

            answer = System.Math.Max(answer, beauty);

            if (remaining > 0) {
                budget -= target - flowers[remaining - 1];
            }
        }

        return answer;
    }
}
