public class Solution {
    public int MinMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.Length;
        bool[] infected = new bool[n];
        bool[] visited = new bool[n];
        int[] saved = new int[n];
        int[] queue = new int[n];

        foreach (int node in initial) {
            infected[node] = true;
        }

        // Find components consisting only of initially uninfected nodes.
        for (int start = 0; start < n; start++) {
            if (infected[start] || visited[start]) {
                continue;
            }

            int head = 0, tail = 0;
            int size = 0;
            int owner = -1; // -1: no source, -2: multiple sources.
            queue[tail++] = start;
            visited[start] = true;

            while (head < tail) {
                int node = queue[head++];
                size++;

                for (int neighbor = 0; neighbor < n; neighbor++) {
                    if (graph[node][neighbor] == 0) {
                        continue;
                    }

                    if (infected[neighbor]) {
                        if (owner == -1) {
                            owner = neighbor;
                        } else if (owner != neighbor) {
                            owner = -2;
                        }
                    } else if (!visited[neighbor]) {
                        visited[neighbor] = true;
                        queue[tail++] = neighbor;
                    }
                }
            }

            // Removing the sole infection source saves this whole component.
            if (owner >= 0) {
                saved[owner] += size;
            }
        }

        int answer = initial[0];
        foreach (int node in initial) {
            if (saved[node] > saved[answer] ||
                (saved[node] == saved[answer] && node < answer)) {
                answer = node;
            }
        }

        return answer;
    }
}
