public class Solution {
    public int MinCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.Length;
        const int Infinity = int.MaxValue / 2;

        // dp[t, city] is the minimum cost to reach city in exactly t minutes.
        int[,] dp = new int[maxTime + 1, n];
        for (int t = 0; t <= maxTime; t++) {
            for (int city = 0; city < n; city++) {
                dp[t, city] = Infinity;
            }
        }

        dp[0, 0] = passingFees[0];
        int answer = Infinity;

        for (int t = 1; t <= maxTime; t++) {
            foreach (int[] edge in edges) {
                int u = edge[0];
                int v = edge[1];
                int travelTime = edge[2];

                if (travelTime > t) {
                    continue;
                }

                int previousTime = t - travelTime;

                if (dp[previousTime, u] != Infinity) {
                    dp[t, v] = System.Math.Min(
                        dp[t, v],
                        dp[previousTime, u] + passingFees[v]
                    );
                }

                if (dp[previousTime, v] != Infinity) {
                    dp[t, u] = System.Math.Min(
                        dp[t, u],
                        dp[previousTime, v] + passingFees[u]
                    );
                }
            }

            answer = System.Math.Min(answer, dp[t, n - 1]);
        }

        return answer == Infinity ? -1 : answer;
    }
}
