public class Solution {
    private static readonly int[] Directions = { -1, 0, 1, 0, -1 };

    public int MinDays(int[][] grid) {
        if (CountIslands(grid) != 1)
            return 0;

        for (int r = 0; r < grid.Length; r++) {
            for (int c = 0; c < grid[0].Length; c++) {
                if (grid[r][c] == 0)
                    continue;

                grid[r][c] = 0;
                bool disconnected = CountIslands(grid) != 1;
                grid[r][c] = 1;

                if (disconnected)
                    return 1;
            }
        }

        // Any finite 4-connected grid island can be disconnected in at most 2 days.
        return 2;
    }

    private int CountIslands(int[][] grid) {
        int rows = grid.Length;
        int cols = grid[0].Length;
        bool[,] visited = new bool[rows, cols];
        int[] queue = new int[rows * cols];
        int islands = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 0 || visited[r, c])
                    continue;

                if (++islands == 2)
                    return 2;

                int head = 0, tail = 0;
                queue[tail++] = r * cols + c;
                visited[r, c] = true;

                while (head < tail) {
                    int cell = queue[head++];
                    int currentRow = cell / cols;
                    int currentCol = cell % cols;

                    for (int d = 0; d < 4; d++) {
                        int nextRow = currentRow + Directions[d];
                        int nextCol = currentCol + Directions[d + 1];

                        if (nextRow < 0 || nextRow >= rows ||
                            nextCol < 0 || nextCol >= cols ||
                            grid[nextRow][nextCol] == 0 ||
                            visited[nextRow, nextCol])
                            continue;

                        visited[nextRow, nextCol] = true;
                        queue[tail++] = nextRow * cols + nextCol;
                    }
                }
            }
        }

        return islands;
    }
}
