public class Solution {
    public int MinDays(int n) {
        var memo = new Dictionary<int, int>();

        int Solve(int oranges) {
            if (oranges <= 1)
                return oranges;

            if (memo.TryGetValue(oranges, out int days))
                return days;

            days = 1 + Math.Min(
                oranges % 2 + Solve(oranges / 2),
                oranges % 3 + Solve(oranges / 3)
            );

            memo[oranges] = days;
            return days;
        }

        return Solve(n);
    }
}
