public class Solution {
    public int MinSessions(int[] tasks, int sessionTime) {
        int n = tasks.Length;
        int totalMasks = 1 << n;
        int[] sessions = new int[totalMasks];
        int[] usedTime = new int[totalMasks];

        sessions[0] = 1;

        for (int mask = 1; mask < totalMasks; mask++) {
            sessions[mask] = n + 1;

            for (int i = 0; i < n; i++) {
                int bit = 1 << i;
                if ((mask & bit) == 0) {
                    continue;
                }

                int previous = mask ^ bit;
                int nextSessions = sessions[previous];
                int nextUsedTime = usedTime[previous] + tasks[i];

                if (nextUsedTime > sessionTime) {
                    nextSessions++;
                    nextUsedTime = tasks[i];
                }

                if (nextSessions < sessions[mask] ||
                    (nextSessions == sessions[mask] &&
                     nextUsedTime < usedTime[mask])) {
                    sessions[mask] = nextSessions;
                    usedTime[mask] = nextUsedTime;
                }
            }
        }

        return sessions[totalMasks - 1];
    }
}
