public class Solution {
    public int[] NextGreaterElements(int[] nums) {
        int n = nums.Length;
        int[] result = new int[n];
        int[] stack = new int[n];
        int count = 0;

        for (int i = 0; i < n; i++) {
            result[i] = -1;
        }

        for (int i = 0; i < 2 * n; i++) {
            int index = i % n;

            while (count > 0 && nums[stack[count - 1]] < nums[index]) {
                result[stack[--count]] = nums[index];
            }

            if (i < n) {
                stack[count++] = index;
            }
        }

        return result;
    }
}
