public class Solution {
    private const long Mod = 1_000_000_007;

    public int NumOfWays(int[] nums) {
        int n = nums.Length;
        int[] left = new int[n];
        int[] right = new int[n];

        for (int i = 0; i < n; i++) {
            left[i] = -1;
            right[i] = -1;
        }

        // Nodes are indexed by their insertion order.
        for (int i = 1; i < n; i++) {
            int current = 0;

            while (true) {
                if (nums[i] < nums[current]) {
                    if (left[current] == -1) {
                        left[current] = i;
                        break;
                    }
                    current = left[current];
                } else {
                    if (right[current] == -1) {
                        right[current] = i;
                        break;
                    }
                    current = right[current];
                }
            }
        }

        long[] factorial = new long[n + 1];
        long[] inverseFactorial = new long[n + 1];
        factorial[0] = 1;

        for (int i = 1; i <= n; i++) {
            factorial[i] = factorial[i - 1] * i % Mod;
        }

        inverseFactorial[n] = Power(factorial[n], Mod - 2);
        for (int i = n; i >= 1; i--) {
            inverseFactorial[i - 1] = inverseFactorial[i] * i % Mod;
        }

        int[] size = new int[n];
        long[] ways = new long[n];

        // Children always have larger indices, so reverse order is bottom-up.
        for (int i = n - 1; i >= 0; i--) {
            int leftSize = left[i] == -1 ? 0 : size[left[i]];
            int rightSize = right[i] == -1 ? 0 : size[right[i]];
            long leftWays = left[i] == -1 ? 1 : ways[left[i]];
            long rightWays = right[i] == -1 ? 1 : ways[right[i]];

            long interleavings = factorial[leftSize + rightSize];
            interleavings = interleavings * inverseFactorial[leftSize] % Mod;
            interleavings = interleavings * inverseFactorial[rightSize] % Mod;

            size[i] = leftSize + rightSize + 1;
            ways[i] = interleavings * leftWays % Mod * rightWays % Mod;
        }

        // Exclude the original ordering.
        return (int)((ways[0] - 1 + Mod) % Mod);
    }

    private static long Power(long value, long exponent) {
        long result = 1;

        while (exponent > 0) {
            if ((exponent & 1) != 0) {
                result = result * value % Mod;
            }

            value = value * value % Mod;
            exponent >>= 1;
        }

        return result;
    }
}
