            interleavings = interleavings * inverseFactorial[leftSize] % Mod;
            interleavings = interleavings * inverseFactorial[rightSize] % Mod;

            size[i] = leftSize + rightSize + 1;
            ways[i] = interleavings * leftWays % Mod * rightWays % Mod;
        }

        // Exclude the original ordering.
        return (int)((ways[0] - 1 + Mod) % Mod);
    }

    private static long Power(long value, long exponent) {
        long result = 1;

        while (exponent > 0) {
            if ((exponent & 1) != 0) {
                result = result * value % Mod;
            }

            value = value * value % Mod;
            exponent >>= 1;
        }

        return result;
    }
}
