public class Solution {
    public bool CanPartitionKSubsets(int[] nums, int k) {
        int sum = 0;
        foreach (int num in nums) {
            sum += num;
        }

        if (sum % k != 0) {
            return false;
        }

        int target = sum / k;
        foreach (int num in nums) {
            if (num > target) {
                return false;
            }
        }

        int stateCount = 1 << nums.Length;
        int[] dp = new int[stateCount];

        for (int mask = 1; mask < stateCount; mask++) {
            dp[mask] = -1;
        }

        for (int mask = 0; mask < stateCount; mask++) {
            if (dp[mask] == -1) {
                continue;
            }

            for (int i = 0; i < nums.Length; i++) {
                int bit = 1 << i;
                if ((mask & bit) != 0) {
                    continue;
                }

                int nextSum = dp[mask] + nums[i];
                if (nextSum <= target) {
                    dp[mask | bit] = nextSum % target;
                }
            }
        }

        return dp[stateCount - 1] == 0;
    }
}
