public class Solution {
    public int MaxSizeSlices(int[] slices) {
        int picks = slices.Length / 3;

        // The first and last slices cannot both be selected.
        return System.Math.Max(
            MaxLinear(slices, 0, slices.Length - 1, picks),
            MaxLinear(slices, 1, slices.Length, picks)
        );
    }

    private int MaxLinear(int[] slices, int start, int end, int picks) {
        const int Impossible = int.MinValue / 2;

        int[] previousTwo = new int[picks + 1];
        int[] previous = new int[picks + 1];
        int[] current = new int[picks + 1];

        for (int j = 1; j <= picks; j++) {
            previousTwo[j] = Impossible;
            previous[j] = Impossible;
        }

        for (int i = start; i < end; i++) {
            current[0] = 0;

            for (int j = 1; j <= picks; j++) {
                current[j] = System.Math.Max(
                    previous[j],
                    previousTwo[j - 1] + slices[i]
                );
            }

            int[] temp = previousTwo;
            previousTwo = previous;
            previous = current;
            current = temp;
        }

        return previous[picks];
    }
}
