public class Solution {
    public int RegionsBySlashes(string[] grid) {
        int n = grid.Length;
        int total = 4 * n * n;
        int[] parent = new int[total];
        int[] size = new int[total];

        for (int i = 0; i < total; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        int regions = total;

        // Each cell has four triangles: top, right, bottom, left.
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                int id = 4 * (row * n + col);
                char cell = grid[row][col];

                if (cell != '/') {
                    regions -= Union(parent, size, id, id + 1);
                    regions -= Union(parent, size, id + 2, id + 3);
                }

                if (cell != '\\') {
                    regions -= Union(parent, size, id, id + 3);
                    regions -= Union(parent, size, id + 1, id + 2);
                }

                if (col + 1 < n) {
                    regions -= Union(parent, size, id + 1, id + 7);
                }

                if (row + 1 < n) {
                    regions -= Union(parent, size, id + 2, id + 4 * n);
                }
            }
        }

        return regions;
    }

    private static int Find(int[] parent, int node) {
        while (parent[node] != node) {
            parent[node] = parent[parent[node]];
            node = parent[node];
        }
        return node;
    }

    private static int Union(int[] parent, int[] size, int a, int b) {
        int rootA = Find(parent, a);
        int rootB = Find(parent, b);

        if (rootA == rootB) {
            return 0;
        }

        if (size[rootA] < size[rootB]) {
            int temp = rootA;
            rootA = rootB;
            rootB = temp;
        }

        parent[rootB] = rootA;
        size[rootA] += size[rootB];
        return 1;
    }
}
