using System;
using System.Collections.Generic;

public class Solution {
    public IList<string> RemoveInvalidParentheses(string s) {
        var result = new List<string>();
        Remove(s, 0, 0, '(', ')', result);
        return result;
    }

    private void Remove(
        string s,
        int scanStart,
        int removalStart,
        char open,
        char close,
        List<string> result
    ) {
        int balance = 0;

        for (int i = scanStart; i < s.Length; i++) {
            if (s[i] == open) balance++;
            else if (s[i] == close) balance--;

            if (balance >= 0) continue;

            for (int j = removalStart; j <= i; j++) {
                if (s[j] == close &&
                    (j == removalStart || s[j - 1] != close)) {
                    Remove(s.Remove(j, 1), i, j, open, close, result);
                }
            }

            return;
        }

        char[] characters = s.ToCharArray();
        Array.Reverse(characters);
        string reversed = new string(characters);

        if (open == '(') {
            Remove(reversed, 0, 0, ')', '(', result);
        } else {
            result.Add(reversed);
        }
    }
}
