public class Solution {
    public int[] RestoreArray(int[][] adjacentPairs) {
        var neighbors = new Dictionary<int, List<int>>();

        foreach (int[] pair in adjacentPairs) {
            int u = pair[0];
            int v = pair[1];

            if (!neighbors.ContainsKey(u))
                neighbors[u] = new List<int>(2);
            if (!neighbors.ContainsKey(v))
                neighbors[v] = new List<int>(2);

            neighbors[u].Add(v);
            neighbors[v].Add(u);
        }

        int[] result = new int[adjacentPairs.Length + 1];

        foreach (var entry in neighbors) {
            if (entry.Value.Count == 1) {
                result[0] = entry.Key;
                break;
            }
        }

        result[1] = neighbors[result[0]][0];

        for (int i = 2; i < result.Length; i++) {
            List<int> next = neighbors[result[i - 1]];
            result[i] = next[0] == result[i - 2] ? next[1] : next[0];
        }

        return result;
    }
}
