public class Solution {
    public IList<IList<int>> ShiftGrid(int[][] grid, int k) {
        int m = grid.Length;
        int n = grid[0].Length;
        int total = m * n;
        k %= total;

        IList<IList<int>> result = new List<IList<int>>(m);

        for (int i = 0; i < m; i++) {
            IList<int> row = new List<int>(n);

            for (int j = 0; j < n; j++) {
                int source = (i * n + j - k + total) % total;
                row.Add(grid[source / n][source % n]);
            }

            result.Add(row);
        }

        return result;
    }
}
