using System.Collections.Generic;

public class Solution {
    public double[] MedianSlidingWindow(int[] nums, int k) {
        var lower = new SortedSet<(int Value, int Index)>();
        var upper = new SortedSet<(int Value, int Index)>();
        double[] result = new double[nums.Length - k + 1];

        void Rebalance() {
            while (lower.Count > upper.Count + 1) {
                var item = lower.Max;
                lower.Remove(item);
                upper.Add(item);
            }

            while (lower.Count < upper.Count) {
                var item = upper.Min;
                upper.Remove(item);
                lower.Add(item);
            }
        }

        for (int i = 0; i < nums.Length; i++) {
            if (i >= k) {
                var outgoing = (Value: nums[i - k], Index: i - k);
                if (!lower.Remove(outgoing)) {
                    upper.Remove(outgoing);
                }
                Rebalance();
            }

            var incoming = (Value: nums[i], Index: i);
            if (lower.Count == 0 || incoming.CompareTo(lower.Max) <= 0) {
                lower.Add(incoming);
            } else {
                upper.Add(incoming);
            }
            Rebalance();

            if (i >= k - 1) {
                result[i - k + 1] = (k % 2 == 1)
                    ? lower.Max.Value
                    : ((long)lower.Max.Value + upper.Min.Value) / 2.0;
            }
        }

        return result;
    }
}
