public class Solution {
    public int SplitArray(int[] nums, int k) {
        int low = 0;
        int high = 0;

        foreach (int num in nums) {
            if (num > low) low = num;
            high += num;
        }

        while (low < high) {
            int mid = low + (high - low) / 2;
            int parts = 1;
            int currentSum = 0;

            foreach (int num in nums) {
                if (currentSum + num > mid) {
                    parts++;
                    currentSum = num;
                    if (parts > k) break;
                } else {
                    currentSum += num;
                }
            }

            if (parts <= k) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        return low;
    }
}
