public class Solution {
    public int MinStickers(string[] stickers, string target) {
        int[] positions = new int[26];
        for (int i = 0; i < target.Length; i++) {
            positions[target[i] - 'a'] |= 1 << i;
        }

        int[][] stickerMasks = new int[stickers.Length][];
        int[] coverage = new int[stickers.Length];
        int totalCoverage = 0;

        for (int i = 0; i < stickers.Length; i++) {
            stickerMasks[i] = new int[stickers[i].Length];
            for (int j = 0; j < stickers[i].Length; j++) {
                int mask = positions[stickers[i][j] - 'a'];
                stickerMasks[i][j] = mask;
                coverage[i] |= mask;
            }
            totalCoverage |= coverage[i];
        }

        int fullMask = (1 << target.Length) - 1;
        if (totalCoverage != fullMask) {
            return -1;
        }

        int[] memo = new int[fullMask + 1];
        for (int i = 0; i < memo.Length; i++) {
            memo[i] = -2;
        }
        memo[fullMask] = 0;

        return Solve(0, fullMask, stickerMasks, coverage, memo);
    }

    private int Solve(
        int mask,
        int fullMask,
        int[][] stickerMasks,
        int[] coverage,
        int[] memo
    ) {
        if (memo[mask] != -2) {
            return memo[mask];
        }

        int missing = fullMask ^ mask;
        int requiredBit = missing & -missing;
        int best = int.MaxValue;

        for (int i = 0; i < stickerMasks.Length; i++) {
            // Some sticker must supply the first missing letter.
            // Since sticker order does not matter, choose that sticker now.
            if ((coverage[i] & requiredBit) == 0) {
                continue;
            }

            int nextMask = mask;
            foreach (int letterMask in stickerMasks[i]) {
                int available = letterMask & ~nextMask;

                // Use this letter for the first matching unfilled position.
                nextMask |= available & -available;
            }

            int remaining = Solve(
                nextMask, fullMask, stickerMasks, coverage, memo
            );

            if (remaining >= 0 && remaining + 1 < best) {
                best = remaining + 1;
            }

            if (best == 1) {
                break;
            }
        }

        memo[mask] = best == int.MaxValue ? -1 : best;
        return memo[mask];
    }
}
