        nextWrite = (nextWrite + 1) % history.Length;

        if (count < history.Length)
            count++;

        TrieNode node = root;
        int position = nextWrite;

        for (int i = 0; i < count; i++)
        {
            position--;
            if (position < 0)
                position = history.Length - 1;

            node = node.Children[history[position] - 'a'];

            if (node == null)
                return false;

            if (node.IsWord)
                return true;
        }

        return false;
    }
}
