public class Solution
{
    private int[,,] earliest;
    private int[,,] latest;

    public int[] EarliestAndLatest(int n, int firstPlayer, int secondPlayer)
    {
        earliest = new int[n + 1, n + 1, n + 1];
        latest = new int[n + 1, n + 1, n + 1];
        return Solve(n, firstPlayer, secondPlayer);
    }

    private int[] Solve(int n, int a, int b)
    {
        if (a + b == n + 1)
            return new int[] { 1, 1 };

        if (earliest[n, a, b] != 0)
            return new int[] { earliest[n, a, b], latest[n, a, b] };

        int nextCount = (n + 1) / 2;

        // Count advancing players before a and before b.
        bool[,] possible = new bool[nextCount + 1, nextCount + 1];
        possible[0, 0] = true;

        for (int left = 1; left <= nextCount; left++)
        {
            int right = n + 1 - left;
            int winner1 = left;
            int winner2 = right;

            if (left == a || left == b)
                winner2 = winner1;
            else if (right == a || right == b)
                winner1 = winner2;

            int addA1 = winner1 < a ? 1 : 0;
            int addB1 = winner1 < b ? 1 : 0;
            int addA2 = winner2 < a ? 1 : 0;
            int addB2 = winner2 < b ? 1 : 0;

            bool[,] next = new bool[nextCount + 1, nextCount + 1];

            for (int x = 0; x < left; x++)
            {
                for (int y = 0; y < left; y++)
                {
                    if (!possible[x, y])
                        continue;

                    next[x + addA1, y + addB1] = true;
                    next[x + addA2, y + addB2] = true;
                }
            }

            possible = next;
        }

        int minimum = int.MaxValue;
        int maximum = 0;

        for (int x = 0; x < nextCount; x++)
        {
            for (int y = x + 1; y < nextCount; y++)
            {
                if (!possible[x, y])
                    continue;

                int[] result = Solve(nextCount, x + 1, y + 1);
                minimum = System.Math.Min(minimum, result[0] + 1);
                maximum = System.Math.Max(maximum, result[1] + 1);
            }
        }

        earliest[n, a, b] = minimum;
        latest[n, a, b] = maximum;
        return new int[] { minimum, maximum };
    }
}
