    public int[] KWeakestRows(int[][] mat, int k) {
        int m = mat.Length;
        int[] soldiers = new int[m];
        int[] indices = new int[m];

        for (int i = 0; i < m; i++) {
            int left = 0;
            int right = mat[i].Length;

            while (left < right) {
                int mid = left + (right - left) / 2;
                if (mat[i][mid] == 1) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }

            soldiers[i] = left;
            indices[i] = i;
        }

        System.Array.Sort(indices, (a, b) => {
            int comparison = soldiers[a].CompareTo(soldiers[b]);
            return comparison != 0 ? comparison : a.CompareTo(b);
        });

        int[] result = new int[k];
        System.Array.Copy(indices, result, k);
        return result;
    }
}
