public class Solution {
    public int[] GetCoprimes(int[] nums, int[][] edges) {
        int n = nums.Length;
        var graph = new List<int>[n];
        for (int i = 0; i < n; i++)
            graph[i] = new List<int>();

        foreach (int[] edge in edges) {
            graph[edge[0]].Add(edge[1]);
            graph[edge[1]].Add(edge[0]);
        }

        var coprime = new List<int>[51];
        for (int value = 1; value <= 50; value++) {
            coprime[value] = new List<int>();
            for (int other = 1; other <= 50; other++) {
                if (Gcd(value, other) == 1)
                    coprime[value].Add(other);
            }
        }

        int[] answer = new int[n];
        int[] depth = new int[n];
        int[] previous = new int[n];
        int[] latest = new int[51];

        for (int value = 0; value <= 50; value++)
            latest[value] = -1;

        // Exit events restore the ancestor state without recursive DFS.
        var stack = new Stack<(int Node, int Parent, bool Exit)>();
        stack.Push((0, -1, false));

        while (stack.Count > 0) {
            var current = stack.Pop();
            int node = current.Node;
            int value = nums[node];

            if (current.Exit) {
                latest[value] = previous[node];
                continue;
            }

            depth[node] = current.Parent == -1
                ? 0
                : depth[current.Parent] + 1;

            int closest = -1;
            foreach (int other in coprime[value]) {
                int ancestor = latest[other];
                if (ancestor != -1 &&
                    (closest == -1 || depth[ancestor] > depth[closest])) {
                    closest = ancestor;
                }
            }
            answer[node] = closest;

            previous[node] = latest[value];
            latest[value] = node;

            stack.Push((node, current.Parent, true));
            foreach (int child in graph[node]) {
                if (child != current.Parent)
                    stack.Push((child, node, false));
            }
        }

        return answer;
    }

    private static int Gcd(int a, int b) {
        while (b != 0) {
            int remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    }
}
