public class Solution {
    public bool ValidateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] inDegree = new int[n];

        for (int i = 0; i < n; i++) {
            if (leftChild[i] != -1 && ++inDegree[leftChild[i]] > 1)
                return false;

            if (rightChild[i] != -1 && ++inDegree[rightChild[i]] > 1)
                return false;
        }

        int root = -1;
        for (int i = 0; i < n; i++) {
            if (inDegree[i] == 0) {
                if (root != -1)
                    return false;
                root = i;
            }
        }

        if (root == -1)
            return false;

        bool[] visited = new bool[n];
        int[] queue = new int[n];
        int head = 0;
        int tail = 0;

        queue[tail++] = root;
        visited[root] = true;

        while (head < tail) {
            int node = queue[head++];
            int left = leftChild[node];
            int right = rightChild[node];

            if (left != -1) {
                if (visited[left])
                    return false;
                visited[left] = true;
                queue[tail++] = left;
            }

            if (right != -1) {
                if (visited[right])
                    return false;
                visited[right] = true;
                queue[tail++] = right;
            }
        }

        return tail == n;
    }
}
