public class Solution
{
    private string[] addends;
    private string answer;
    private int[] digits;
    private bool[] used;
    private bool[] nonZero;

    public bool IsSolvable(string[] words, string result)
    {
        addends = words;
        answer = result;
        digits = new int[26];
        used = new bool[10];
        nonZero = new bool[26];

        for (int i = 0; i < 26; i++)
            digits[i] = -1;

        int maxLength = 0;
        foreach (string word in words)
        {
            maxLength = System.Math.Max(maxLength, word.Length);
            if (word.Length > 1)
                nonZero[word[0] - 'A'] = true;
        }

        if (result.Length < maxLength || result.Length > maxLength + 1)
            return false;

        if (result.Length > 1)
            nonZero[result[0] - 'A'] = true;

        return Search(0, 0, 0);
    }

    private bool Search(int column, int row, int sum)
    {
        if (column == answer.Length)
            return sum == 0;

        if (row == addends.Length)
        {
            int letter = answer[answer.Length - 1 - column] - 'A';
            int required = sum % 10;
            int carry = sum / 10;

            if (digits[letter] != -1)
            {
                return digits[letter] == required &&
                       Search(column + 1, 0, carry);
            }

            if (used[required] || (required == 0 && nonZero[letter]))
                return false;

            digits[letter] = required;
            used[required] = true;

            if (Search(column + 1, 0, carry))
                return true;

            digits[letter] = -1;
            used[required] = false;
            return false;
        }

        string word = addends[row];
        if (column >= word.Length)
            return Search(column, row + 1, sum);

        int current = word[word.Length - 1 - column] - 'A';

        if (digits[current] != -1)
            return Search(column, row + 1, sum + digits[current]);

        for (int digit = 0; digit <= 9; digit++)
        {
            if (used[digit] || (digit == 0 && nonZero[current]))
                continue;

            digits[current] = digit;
            used[digit] = true;

            if (Search(column, row + 1, sum + digit))
                return true;

            digits[current] = -1;
            used[digit] = false;
        }

        return false;
    }
}
