public class Solution {
    public bool IsMatch(string s, string p) {
        int i = 0;
        int j = 0;
        int starIndex = -1;
        int starMatchEnd = 0;

        while (i < s.Length) {
            if (j < p.Length && (p[j] == '?' || p[j] == s[i])) {
                i++;
                j++;
            } else if (j < p.Length && p[j] == '*') {
                starIndex = j++;
                starMatchEnd = i;
            } else if (starIndex != -1) {
                j = starIndex + 1;
                i = ++starMatchEnd;
            } else {
                return false;
            }
        }

        while (j < p.Length && p[j] == '*') {
            j++;
        }

        return j == p.Length;
    }
